"""A collection of tools which simulates common functions used for settings.

Ported from ToolSandbox ``tools/setting.py``. Device settings are a single row
in the ``device_settings`` table.
"""

from typing import Dict, Literal, cast

from . import db
from .validators import validate_type

_BOOLEAN_SETTINGS = {"cellular", "wifi", "location_service", "low_battery_mode"}


def _require_settings() -> Dict[str, object]:
    row = db.get_settings_row()
    if row is None:
        raise KeyError("No device settings row found")
    return row


def set_boolean_settings(setting_name: str, on: bool) -> None:
    """Utility for setting boolean settings. Not exposed as a tool.

    Raises:
        KeyError:   If setting_name is not a boolean setting column
        ValueError: If the setting is already in the requested state
    """
    validate_type(setting_name, "setting_name", str)
    validate_type(on, "on", bool)

    row = _require_settings()
    if setting_name not in _BOOLEAN_SETTINGS:
        raise KeyError(f"{setting_name} is not a boolean column")
    if bool(row[setting_name]) == on:
        raise ValueError(f"{setting_name} already {('disabled', 'enabled')[int(on)]}")
    db.update("device_settings", "device_id", cast(str, row["device_id"]), {setting_name: on})


def get_boolean_settings(setting_name: str) -> bool:
    """Utility for getting boolean settings. Not exposed as a tool.

    Raises:
        KeyError:   If setting_name is not a boolean setting column
    """
    validate_type(setting_name, "setting_name", str)
    row = _require_settings()
    if setting_name not in _BOOLEAN_SETTINGS:
        raise KeyError(f"{setting_name} is not a boolean column")
    return bool(row[setting_name])


def set_low_battery_mode_status(on: bool) -> None:
    """Enable / Disable low battery mode.

    Raises:
        ValueError: If low battery mode is already turned on / off
    """
    validate_type(on, "on", bool)
    set_boolean_settings(setting_name="low_battery_mode", on=on)
    # Automatically turn off dependent services when low battery mode is on.
    if on:
        for dependent_setting in ["cellular", "wifi", "location_service"]:
            try:
                set_boolean_settings(dependent_setting, on=False)
            except ValueError:
                pass


def get_low_battery_mode_status() -> bool:
    """Request low battery mode status."""
    return get_boolean_settings("low_battery_mode")


def set_location_service_status(on: bool) -> None:
    """Enable / Disable location service.

    Raises:
        ValueError:      If location service is already turned on / off
        PermissionError: If low battery mode is on
    """
    if on and get_low_battery_mode_status():
        raise PermissionError("Location service cannot be turned on in low battery mode")
    set_boolean_settings(setting_name="location_service", on=on)


def get_location_service_status() -> bool:
    """Request location service status."""
    return get_boolean_settings("location_service")


def set_cellular_service_status(on: bool) -> None:
    """Enable / Disable cellular service.

    Raises:
        ValueError:      If cellular service is already turned on / off
        PermissionError: If low battery mode is on
    """
    validate_type(on, "on", bool)
    if on and get_low_battery_mode_status():
        raise PermissionError("Cellular service cannot be turned on in low battery mode")
    set_boolean_settings(setting_name="cellular", on=on)


def get_cellular_service_status() -> bool:
    """Request cellular service status."""
    return get_boolean_settings("cellular")


def set_wifi_status(on: bool) -> None:
    """Enable / Disable wifi.

    Raises:
        ValueError:      If wifi is already turned on / off
        PermissionError: If low battery mode is on
    """
    validate_type(on, "on", bool)
    if on and get_low_battery_mode_status():
        raise PermissionError("Wifi cannot be turned on in low battery mode")
    set_boolean_settings(setting_name="wifi", on=on)


def get_wifi_status() -> bool:
    """Request wifi status."""
    return get_boolean_settings("wifi")


def get_current_location() -> Dict[Literal["latitude", "longitude"], float]:
    """Request current location latitude and longitude.

    Raises:
        PermissionError: If location service is not turned on
    """
    if not get_location_service_status():
        raise PermissionError("Location service is not enabled.")
    row = _require_settings()
    return {
        "latitude": cast(float, row["latitude"]),
        "longitude": cast(float, row["longitude"]),
    }

def _coerce(row: sqlite3.Row) -> Dict[str, Any]:
    """Convert a SQLite row into a dict with booleans/floats normalized."""
    out: Dict[str, Any] = {}
    for key in row.keys():
        value = row[key]
        if value is None:
            out[key] = None
        elif key in _BOOLEAN_COLUMNS:
            out[key] = bool(value)
        elif key in _FLOAT_COLUMNS:
            out[key] = float(value)
        else:
            out[key] = value
    return out


def fetch_rows(table: str, columns: List[str]) -> List[Dict[str, Any]]:
    """Fetch all rows of ``table`` (selected ``columns``) as coerced dicts."""
    conn = connect()
    try:
        cur = conn.execute(f"SELECT {', '.join(columns)} FROM {_phys(table)}")
        return [_coerce(r) for r in cur.fetchall()]
    finally:
        conn.close()


# ── Filter helpers (mirror tool_sandbox.common.utils) ─────────────────────────
def exact_match_filter(rows: List[Dict[str, Any]], column: str, value: Any) -> List[Dict[str, Any]]:
    return [r for r in rows if r.get(column) == value]


def gt_eq_filter(rows: List[Dict[str, Any]], column: str, value: Any) -> List[Dict[str, Any]]:
    return [r for r in rows if r.get(column) is not None and r[column] >= value]


def lt_eq_filter(rows: List[Dict[str, Any]], column: str, value: Any) -> List[Dict[str, Any]]:
    return [r for r in rows if r.get(column) is not None and r[column] <= value]


def fuzzy_match_filter(
    rows: List[Dict[str, Any]], column: str, value: Any, threshold: float = 90
) -> List[Dict[str, Any]]:
    """Fuzzy match ``value`` against ``column`` using rapidfuzz WRatio.

    Preserves the original behavior, including ``process.extract``'s default
    top-5 limit and ``utils.default_process`` normalization.
    """
    choices = ["" if r.get(column) is None else str(r[column]) for r in rows]
    matches = process.extract(
        query=value,
        choices=choices,
        processor=utils.default_process,
        scorer=fuzz.WRatio,
        score_cutoff=threshold,
    )
    return [rows[m[-1]] for m in matches]


# A criterion is (column, value, method, kwargs).
Criterion = Tuple[str, Any, Callable[..., List[Dict[str, Any]]], Dict[str, Any]]


def search(rows: List[Dict[str, Any]], criteria: List[Criterion]) -> List[Dict[str, Any]]:
    """Apply criteria in order, skipping any whose value is NOT_GIVEN.

    Raises:
        ValueError: if every criterion's value is NOT_GIVEN (matches original).
    """
    if all(value is NOT_GIVEN for _, value, _, _ in criteria):
        raise ValueError(
            "No search criteria are given. At least one search criteria should be "
            f"provided among {tuple(name for name, _, _, _ in criteria)}"
        )
    result = rows
    for column, value, method, kwargs in criteria:
        if value is not NOT_GIVEN:
            result = method(result, column, value, **kwargs)
    return result


# ── Write helpers ─────────────────────────────────────────────────────────────
def insert(table: str, row: Dict[str, Any]) -> None:
    cols = list(row.keys())
    placeholders = ", ".join("?" for _ in cols)
    conn = connect()
    try:
        conn.execute(
            f"INSERT INTO {_phys(table)} ({', '.join(cols)}) VALUES ({placeholders})",
            [_to_sql(v) for v in row.values()],
        )
        conn.commit()
    finally:
        conn.close()


def update(table: str, id_column: str, id_value: str, updates: Dict[str, Any]) -> int:
    """Update matching rows. Returns the number of rows affected."""
    assignments = ", ".join(f"{c} = ?" for c in updates)
    params = [_to_sql(v) for v in updates.values()] + [id_value]
    conn = connect()
    try:
        cur = conn.execute(
            f"UPDATE {_phys(table)} SET {assignments} WHERE {id_column} = ?", params
        )
        conn.commit()
        return cur.rowcount
    finally:
        conn.close()


def delete(table: str, id_column: str, id_value: str) -> int:
    """Delete matching rows. Returns the number of rows affected."""
    conn = connect()
    try:
        cur = conn.execute(f"DELETE FROM {_phys(table)} WHERE {id_column} = ?", (id_value,))
        conn.commit()
        return cur.rowcount
    finally:
        conn.close()


def count(table: str, id_column: str, id_value: str) -> int:
    conn = connect()
    try:
        cur = conn.execute(
            f"SELECT COUNT(*) FROM {_phys(table)} WHERE {id_column} = ?", (id_value,)
        )
        return int(cur.fetchone()[0])
    finally:
        conn.close()


def get_settings_row() -> Optional[Dict[str, Any]]:
    rows = fetch_rows(
        "device_settings",
        [
            "device_id",
            "cellular",
            "wifi",
            "location_service",
            "low_battery_mode",
            "latitude",
            "longitude",
        ],
    )
    return rows[0] if rows else None


def _to_sql(value: Any) -> Any:
    """Convert Python values to SQLite-storable ones (bool -> int)."""
    if isinstance(value, bool):
        return int(value)
    return value
